def find_max(nums):
    max_value = nums[0]
    for n in nums:
        if n > max_value:
            max_value = n
    return max_value

values = [-3, -7, -2, -9, -4]
print(find_max(values))

def count_vowels(text):
    vowels = "aeiouAEIOU"
    count = 0
    for ch in text:
        if ch in vowels:
            count += 1
    return count

text = input("Enter text: ")
print("Vowels:", count_vowels(text))
